        };
        const r = await ck.call(this, 'PUT', '/api/admin/bible/salmo-do-dia', payload);
        if (r.statusCode >= 200 && r.statusCode < 300) {
          outMessage = `🛡️ *Salmo do Dia Atualizado com Sucesso!*

📅 *Data:* ${targetDate}
📖 *Salmo:* ${args.ref}
📜 *Texto:*
_"${args.texto}"_

🕊️ *Meditação:*
${args.reflexao || 'Que a paz do Senhor guarde a sua vida.'}

✅ _Salvo e em exibição na plataforma!_`;
        } else {
          outMessage = `⚠️ Erro ao atualizar salmo: ${r.body?.message || JSON.stringify(r.body)}`;
        }

      // 3. GERENCIAR DEVOCIONAIS 365 (ADMIN)
      } else if (fnName === 'admin_manage_devotional_365') {
        const day = Number(args.day || 1);
        if (args.action === 'save') {
          const payload = {
            titulo: args.titulo || 'Devocional Diário',
