            outMessage = `⚠️ Erro ao salvar devocional: ${r.body?.message || JSON.stringify(r.body)}`;
          }
        } else if (args.action === 'generate_ai') {
          const year = new Date().getFullYear();
          const r = await ck.call(this, 'POST', `/api/admin/bible/devotionals-365/day/${day}/generate-ai`, {
