      // 4. PROSPERIDADE ANTES DE DORMIR (ADMIN)
      } else if (fnName === 'admin_manage_prosperidade_dormir') {
        const n = Number(args.activation_number || 1);
        if (args.action === 'save') {
          const payload = {
            titulo: args.titulo || 'Ativação Noturna',
            proverbs_ref: args.proverbs_ref || '',
