        } else if (args.action === 'publish') {
          const pub = args.published !== false;
          const r = await ck.call(this, 'PATCH', `/api/admin/bible/prosperidade/${n}/publish`, { published: pub });
          outMessage = r.statusCode < 300 ? `📢 *Ativação #${n} ${pub ? 'Publicada com Sucesso! Já visível para todos.' : 'Despublicada (Rascunho)'}*` : `⚠️ Erro ao alterar status: ${r.body?.message}`;
        } else if (args.action === 'generate_ai') {
          const r = await ck.call(this, 'POST', `/api/admin/bible/prosperidade/${n}/generate-ai`);
          if (r.statusCode >= 200 && r.statusCode < 300) {
            const data = r.body?.data || {};
            outMessage = `⚡ *Ativação #${n} Gerada com IA (Do Fracasso ao Legado)!*

💎 *${data.titulo || 'Ativação Noturna'}*
📖 *Versículo:* ${data.proverbs_ref || ''}

🗣️ *Decreto Noturno:*
_"${data.decreto_entrada || data.sentenca_ativacao || ''}"_

✅ _Salva com sucesso no banco de dados!_`;
          } else {
            outMessage = `⚠️ Falha ao gerar com IA: ${r.body?.message || JSON.stringify(r.body)}`;
          }
        } else {
          const r = await ck.call(this, 'GET', `/api/admin/bible/prosperidade/${n}`);
          const d = r.body?.data || {};
          outMessage = `🌙 *Ativação #${n}:* ${d.titulo || ''}
*Decreto:* ${d.decreto_entrada || ''}
*Status:* ${d.published ? 'Publicada' : 'Rascunho'}`;
        }

      // 5. GERAR ESTUDO POR LIVRO COM IA (ADMIN)
      } else if (fnName === 'admin_generate_book_study') {
        const bookId = String(args.book_id || '').toLowerCase().trim();
        const r = await ck.call(this, 'POST', `/api/admin/bible/study/book/${bookId}/generate-ai`);
        if (r.statusCode >= 200 && r.statusCode < 300) {
          outMessage = `📚 *Estudo do Livro de ${bookId.toUpperCase()} Gerado com Sucesso!*\n\nO estudo exegético completo com introdução, contexto histórico, temas principais e divisão por capítulos foi gravado e já está acessível no módulo de estudos da Bíblia! 📖👑`;
        } else {
          outMessage = `⚠️ Falha ao gerar estudo: ${r.body?.message || JSON.stringify(r.body)}`;
        }

      // 6. CONSULTAS COMUNS (VERSÍCULO, SALMO, ETC.)
      } else if (fnName === 'get_verse_of_day') {
        const query = args.date ? '?date=' + encodeURIComponent(args.date) : '';
        const r = await ck.call(this, 'GET', '/api/bible/verse-of-day' + query);
        const data = (r.body && r.body.data) || {};
        const ref = data.ref || 'Palavra do Dia';
        const versiculo = data.texto || 'Lâmpada para os meus pés é tua palavra e luz, para o meu caminho.';
        const reflexao = data.reflexao || 'Guarde esta promessa em seu coração hoje.';
        outMessage = `📖 *Versículo do Dia | Conecta King*

"*${versiculo}*"

📍 *${ref}*

🕊️ *Reflexão:*
${reflexao}

Que esta Palavra alimente o seu espírito hoje! 🙏`;
      } else if (fnName === 'get_devocional_do_dia') {
        const r = await ck.call(this, 'GET', '/api/bible/devocional-do-dia');
        const d = (r.body && r.body.data) || {};
        const titulo = d.titulo || d.title || 'Devocional Diário';
        const passagem = d.passagem || d.reference || d.ref || 'Escrituras Sagradas';
        const texto = d.texto || d.content || d.meditacao || '';
        const oracao = d.oracao || d.prayer || '';
        outMessage = `✨ *Devocional do Dia:* ${titulo}

📖 *Texto Base:* ${passagem}

${texto}

${oracao ? '🙏 *Oração:*
_' + oracao + '_

' : ''}Amém! Que Deus abençoe sua jornada.`;
      } else if (fnName === 'get_salmo_do_dia') {
        const r = await ck.call(this, 'GET', '/api/bible/salmo-do-dia');
        const s = (r.body && r.body.data) || {};
        const ref = s.ref || 'Salmos';
        const texto = s.texto || '';
        const reflexao = s.reflexao || '';
        outMessage = `🛡️ *Salmo do Dia:* ${ref}

"${texto}"

${reflexao ? '🕊️ *Meditação:*
' + reflexao + '

' : ''}Que o Senhor seja o seu refúgio e fortaleza hoje! 🙌`;
      } else if (fnName === 'get_prosperidade_hoje') {
        const path = args.day ? '/api/bible/prosperidade/ativacao/' + args.day : '/api/bible/prosperidade/hoje';
        const r = await ck.call(this, 'GET', path);
        const p = (r.body && r.body.data) || {};
        const num = p.numero || p.day || p.dia || '365';
        const titulo = p.titulo || p.title || 'Ativação Bíblica de Prosperidade';
        const versiculo = p.versiculo || p.verse || '';
        const declaracao = p.declaracao || p.affirmation || '';
        const chave = p.chave || p.chave_prosperidade || p.principio || '';
        const acao = p.acao_pratica || p.action || '';
        outMessage = `🌙 *Ativação Noturna de Prosperidade #${num}*

💎 *${titulo}*

📖 *Princípio Bíblico:*
"${versiculo}"

${chave ? '🔑 *Chave de Sabedoria:* ' + chave + '

' : ''}${declaracao ? '🗣️ *Declaração de Fé:*
_"' + declaracao + '"_

' : ''}${acao ? '🎯 *Passo Prático:*
' + acao + '

' : ''}Deus tem prazer na prosperidade integral da sua vida!`;
      } else if (fnName === 'get_bible_text') {
        const bookId = String(args.book_id || 'salmos').toLowerCase();
        const cap = Number(args.chapter || 1);
        const r = await ck.call(this, 'GET', `/api/bible/book/${bookId}/${cap}`);
        const data = (r.body && r.body.data) || {};
        const bookName = data.book?.name || bookId.toUpperCase();
        const verses = data.verses || data.versiculos || [];
        if (Array.isArray(verses) && verses.length > 0) {
          const sample = verses.slice(0, 10).map(v => `*${v.number || v.verse}* ${v.text}`).join('

');
          outMessage = `📖 *${bookName} ${cap}*

${sample}${verses.length > 10 ? '

_(Exibindo os primeiros 10 versículos de ' + verses.length + ' motivado por espaço no Telegram)_' : ''}`;
        } else {
          outMessage = `📖 *Leitura de ${bookName} ${cap}* consultada na plataforma.`;
        }
      } else if (fnName === 'generate_sermon_outline') {
        const theme = args.theme;
        const pass = args.passage || 'Escrituras';
        const aud = args.audience ? ` (Público: ${args.audience})` : '';
        const sermonRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pregador e mestre bíblico expositivo. Crie um esboço claro de sermão contendo: 1. Título impactante; 2. Texto Base com contexto; 3. Introdução que prenda a atenção; 4. Três pontos principais expositivos bem alicerçados nas escrituras; 5. Aplicação prática para o cotidiano; 6. Conclusão e apelo/oração.' },
            { role: 'user', content: `Elabore um esboço de pregação sobre o tema: "${theme}", baseado em "${pass}"${aud}.` }
          ]
        });
        outMessage = sermonRes.body?.choices?.[0]?.message?.content || `📋 *Esboço de Pregação: ${theme}*

📖 Base: ${pass}`;
      } else if (fnName === 'pastoral_prayer_counsel') {
        const prayerRes = await openaiCall.call(this, {
          model,
          temperature: 0.4,
          messages: [
            { role: 'system', content: 'Você é um pastor acolhedor e cheio de fé. Escreva uma oração pastoral profunda, sincera e bíblica, trazendo consolo, esperança e paz ao coração da pessoa, finalizando com uma bênção sacerdotal.' },
            { role: 'user', content: `Faça uma oração pastoral para ${args.name || firstName}, que necessita de intercessão e direção sobre: ${args.need}.` }
          ]
        });
        outMessage = prayerRes.body?.choices?.[0]?.message?.content || `🙏 Que a paz que excede todo entendimento guarde o seu coração em Cristo Jesus.`;
      }
    } else {
      outMessage = choice?.content || `A paz do Senhor, ${firstName}! Estou aqui como Administrador e Conselheiro Bíblico da Conecta King. O que você gostaria de criar, editar ou estudar na Palavra hoje?`;
    }

    session.history.push({ role: 'user', content: inputForAi });
    session.history.push({ role: 'assistant', content: outMessage });
    if (session.history.length > 12) session.history.splice(0, 2);
  }
} catch (e) {
  outMessage = '🕊️ Graça e Paz! Ocorreu uma oscilação momentânea: ' + String(e.message || e).slice(0, 200) + '

Como posso abençoar seus estudos na Palavra hoje?';
}

return [{ json: { ...prev, outMessage } }];
